namespace Puck.SdfVm;

/// <summary>The mesh irradiance probe record shared by the CPU tracer and views shader, generated by <see cref="SdfIsaHlsl"/>.
/// It holds a key, six sky halves, eighteen radiance halves, light visibility bits, the relocated origin, and an octahedral map of first-hit surface support.</summary>
public static class SdfMeshIrradianceProbe {
    /// <summary>The octahedral depth map's width and height, without duplicated border texels.</summary>
    public const int DepthSize = 12;
    /// <summary>The first surface word: FP16 perpendicular distance and two signed octahedral normal bytes.
    /// A negative distance means a miss to that reach.</summary>
    public const int DepthWord = 19;
    /// <summary>The number of packed surface words, one texel per word.</summary>
    public const int DepthWords = (DepthSize * DepthSize);
    /// <summary>The signed octahedral normal byte's scale; axis normals remain exact.</summary>
    public const float DepthNormalScale = 127f;
    /// <summary>The surface gap over which an angular tap closes, in metres, smaller than normal bias.</summary>
    public const float DepthSurfaceFade = 0.02f;
    /// <summary>The words one probe takes in the volume table.</summary>
    public const int ProbeWords = (DepthWord + DepthWords);
    /// <summary>Two words of FP16 offset XYZ and back-face share. Every directional read uses this relocated origin.</summary>
    public const int OffsetWord = 17;
    /// <summary>The least distance in metres between a probe and any surface.</summary>
    public const float Clearance = 0.1f;
    /// <summary>The first word of the traced light visibility bits, one bit per lights-table record.</summary>
    public const int LightsWord = 13;
    /// <summary>The number of light visibility words.</summary>
    public const int LightWords = 4;
    /// <summary>The flag a written probe carries.</summary>
    public const uint WrittenFlag = (1u << 30);
    /// <summary>The flag of a probe no candidate could move into the open.</summary>
    public const uint InvalidFlag = (1u << 31);
    /// <summary>The receiver's normal bias in metres, smaller than the thinnest wall, independent of probe spacing.</summary>
    public const float NormalBias = 0.05f;
    /// <summary>The hit footprint share below which an edge tap cannot extend a finite block.</summary>
    public const float DepthCoverageStart = 0.5f;
    /// <summary>Scales the footprint's closing ramp to complete at three-quarter coverage.</summary>
    public const float DepthCoverageScale = 4f;
}
